import type { RaceBundle, SeasonData } from '@/types';
import { loadSeedRace, loadSeedSeason } from '@/data/seed2026';

/**
 * Offline-first loaders. Browser never calls api.openf1.org:
 *   1. try the static bundle under /data/2026/ (generated by scripts/fetch_2026_season.py)
 *   2. fall back to data embedded in the JS bundle (src/data/seed)
 */
const BASE = `${import.meta.env.BASE_URL}data/2026`;

let seasonPromise: Promise<SeasonData> | null = null;
const raceCache = new Map<string, Promise<RaceBundle>>();

async function getJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  return (await res.json()) as T;
}

export function loadSeason(): Promise<SeasonData> {
  if (!seasonPromise) {
    seasonPromise = getJson<SeasonData>(`${BASE}/season.json`).catch(() => loadSeedSeason());
  }
  return seasonPromise;
}

export function loadRace(slug: string): Promise<RaceBundle> {
  let p = raceCache.get(slug);
  if (!p) {
    p = getJson<RaceBundle>(`${BASE}/races/${slug}.json`).catch(async (err) => {
      const seed = await loadSeedRace(slug);
      if (seed) return seed;
      raceCache.delete(slug);
      throw err;
    });
    raceCache.set(slug, p);
  }
  return p;
}
